ALTER TABLE public.profiles
ADD COLUMN IF NOT EXISTS tutorial_completed boolean NOT NULL DEFAULT false,
ADD COLUMN IF NOT EXISTS tutorial_step integer NOT NULL DEFAULT 0,
ADD COLUMN IF NOT EXISTS tutorial_started_at timestamp with time zone,
ADD COLUMN IF NOT EXISTS tutorial_chapter_statuses jsonb NOT NULL DEFAULT '["pending","pending","pending","pending","pending","pending","pending","pending","pending","pending"]'::jsonb;

CREATE INDEX IF NOT EXISTS idx_profiles_tutorial_completed ON public.profiles (tutorial_completed);

ON CONFLICT (key) DO UPDATE SET
category = EXCLUDED.category,
value_pt = EXCLUDED.value_pt,
value_en = EXCLUDED.value_en,
value_fr = EXCLUDED.value_fr,
value_es = EXCLUDED.value_es,
updated_at = now();